#!/usr/bin/env node
/**
 * Packs the dream's voxel models and worlds (docs/dream/v3/data) into src/skin/dream/models.gen.ts
 * (docs/dream/v3/03-models.md, section 2). The generated file is never edited by hand: change the pack's data and run
 * `node tools/dream/packModels.mjs` again. src/skin/dream/__tests__/models.test.ts fails when the two differ.
 *
 * Every box keeps its exact cells: [x0, y0, z0, x1, y1, z1, colour, part, season], with one shared list of colour
 * tokens ("material:step" of LADDER, or "glow:<name>") and one of part names.
 */
import { readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '../..');
const data = join(root, 'docs/dream/v3/data');
export const OUT = join(root, 'src/skin/dream/models.gen.ts');

const num = (v) => (Number.isInteger(v) ? String(v) : String(Math.round(v * 1e4) / 1e4));
const row = (a) => `[${a.map((v) => (typeof v === 'number' ? num(v) : JSON.stringify(v))).join(',')}]`;

/** The generated module's text. */
export function render() {
  const files = readdirSync(join(data, 'models')).filter((f) => f.endsWith('.json') && f !== 'index.json').sort();
  const models = files.map((f) => JSON.parse(readFileSync(join(data, 'models', f), 'utf8')));
  const worlds = JSON.parse(readFileSync(join(data, 'worlds.json'), 'utf8'));
  const palette = JSON.parse(readFileSync(join(data, 'palette.json'), 'utf8'));
  const colours = [], parts = [];
  const ci = (c) => { let i = colours.indexOf(c); if (i < 0) { i = colours.length; colours.push(c); } return i; };
  const pi = (p) => { let i = parts.indexOf(p); if (i < 0) { i = parts.length; parts.push(p); } return i; };
  const out = [];
  out.push('// Generated by tools/dream/packModels.mjs from docs/dream/v3/data. Do not edit: change the data and run it again.');
  out.push('/* eslint-disable */');
  const body = [];
  body.push('export const MODELS: Record<string, ModelData> = {');
  for (const m of models) {
    const boxes = m.boxes.map((b) => row([...b.b, ci(b.c), pi(b.part), b.season ? 1 : 0])).join(',');
    const lights = m.lights.map((l) => row([...l.at, ci(l.c), l.radius_m, l.strength])).join(',');
    body.push(`  ${JSON.stringify(m.id)}: { cell: ${num(m.cell_m)}, bounds: ${row(m.bounds_cells)}, lights: [${lights}], boxes: [${boxes}] },`);
  }
  body.push('};');
  body.push(`export const STRIP_M = ${num(worlds.strip_m)}, BAY_M = ${num(worlds.bay_m)}, GROUND_Y_M = ${num(worlds.ground_y_m)};`);
  body.push(`export const ROWS = ${JSON.stringify(Object.fromEntries(Object.entries(worlds.rows).map(([k, v]) => [k, { z: v.z_m, tint: v.tint }])))} as const;`);
  body.push('export const WORLDS: Record<1 | 2 | 3, WorldData> = {');
  for (const [k, w] of Object.entries(worlds.worlds)) {
    const placed = w.models_placed.map((p) => row([p.model, p.x, p.y, p.z, p.tint ?? -1, p.parts ? p.parts.map(pi).reduce((s, i) => s | (1 << i), 0) : 0])).join(',');
    const boxes = w.boxes_placed.map((b) => row([...b.b, ci(b.c), b.tint ?? -1])).join(',');
    const sheets = w.light_sheets.map((s) => row([...s.b, ci(s.c), s.amount])).join(',');
    body.push(`  ${k}: { sky: ${JSON.stringify(w.sky)}, fog: ${JSON.stringify({ start: w.fog.start_m, end: w.fog.end_m })}, placed: [${placed}], boxes: [${boxes}], sheets: [${sheets}] },`);
  }
  body.push('};');
  body.push(`export const GLOW: Record<string, string> = ${JSON.stringify(palette.glow)};`);
  out.push(`export const COLOURS: readonly string[] = ${JSON.stringify(colours)};`);
  out.push(`export const PARTS: readonly string[] = ${JSON.stringify(parts)};`);
  out.push('/** A model: its cell in metres, its bounds in cells, its glows [x, y, z, colour, radius_m, strength], its boxes [x0, y0, z0, x1, y1, z1, colour, part, season]. */');
  out.push('export interface ModelData { cell: number; bounds: readonly number[]; lights: readonly (readonly number[])[]; boxes: readonly (readonly number[])[] }');
  out.push('/** A world: its sky and haze, its models [id, x, y, z, tint or -1, parts mask or 0], its plain boxes [x0, y0, z0, x1, y1, z1, colour, tint or -1] in metres, its sheets of light [x0, y0, x1, y1, z, colour, amount]. */');
  out.push('export interface WorldData { sky: Record<string, string>; fog: { start: number; end: number }; placed: readonly (readonly (string | number)[])[]; boxes: readonly (readonly number[])[]; sheets: readonly (readonly number[])[] }');
  return [...out, ...body].join('\n') + '\n';
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  writeFileSync(OUT, render());
  console.log(`wrote ${OUT}`);
}
